
import { useEffect, useState } from 'react'
import { createRoot } from 'react-dom/client'
import type { Session } from '@supabase/supabase-js'
import App from './App'
import Auth from './Auth'
import SuperAdmin from './SuperAdmin'
import { supabase } from './supabase'
import './index.css'
function PublicInfoPage({kind}:{kind:'about'|'privacy'}) {
 const defaults = kind==='about' ? {title:'About CODEVEX',body:'CODEVEX is a customer relationship management platform.'} : {title:'Privacy Policy',body:'The privacy policy content will be published by CODEVEX administration.'}
 let saved:any=null; try { saved=JSON.parse(localStorage.getItem('cvx-pages-draft')||'null')?.[kind] } catch {}
 const title=saved?.published && saved.title ? saved.title : defaults.title
 const body=saved?.published && saved.body ? saved.body : defaults.body
 return <main style={{maxWidth:900,margin:'40px auto',padding:24,fontFamily:'Arial,sans-serif',color:'#17233b'}}><a href="/" style={{color:'#245fe5'}}>← CODEVEX</a><h1 style={{fontSize:32}}>{title}</h1><div style={{whiteSpace:'pre-wrap',lineHeight:1.8}}>{body}</div></main>
}


type AccountType = 'platform' | 'company' | null

function Root() {
  const [session, setSession] = useState<Session | null>(null)
    const [accountType, setAccountType] = useState<AccountType>(null)
      const [loading, setLoading] = useState(true)
        const [checkingAccess, setCheckingAccess] = useState(false)

          useEffect(() => {
              const { data: listener } = supabase.auth.onAuthStateChange(
                    (_event, newSession) => {
                            setSession(newSession)
                                    if (!newSession) {
                                              setAccountType(null)
                                                        setCheckingAccess(false)
                                                                }
                                                                      }
                                                                          )

                                                                              supabase.auth.getSession().then(({ data }) => {
                                                                                    setSession(data.session)
                                                                                          setLoading(false)
                                                                                              })

                                                                                                  return () => listener.subscription.unsubscribe()
                                                                                                    }, [])

                                                                                                      useEffect(() => {
                                                                                                          let cancelled = false

                                                                                                              async function verifyAccount() {
                                                                                                                    if (!session?.user) {
                                                                                                                            setAccountType(null)
                                                                                                                                    return
                                                                                                                                          }

                                                                                                                                                setCheckingAccess(true)

                                                                                                                                                      try {
                                                                                                                                                              const { data: admin, error: adminError } = await supabase
                                                                                                                                                                        .from('platform_admins')
                                                                                                                                                                                  .select('user_id')
                                                                                                                                                                                            .eq('user_id', session.user.id)
                                                                                                                                                                                                      .maybeSingle()

                                                                                                                                                                                                              if (adminError) throw adminError

                                                                                                                                                                                                                      if (admin) {
                                                                                                                                                                                                                                if (!cancelled) setAccountType('platform')
                                                                                                                                                                                                                                          return
                                                                                                                                                                                                                                                  }

                                                                                                                                                                                                                                                          const { data: profile, error: profileError } = await supabase
                                                                                                                                                                                                                                                                    .from('profiles')
                                                                                                                                                                                                                                                                              .select('role, approval_status')
                                                                                                                                                                                                                                                                                        .eq('id', session.user.id)
                                                                                                                                                                                                                                                                                                  .maybeSingle()

                                                                                                                                                                                                                                                                                                          if (profileError) throw profileError
                                                                                                                                                                                                                                                                                                                  if (!profile || profile.approval_status !== 'approved') {
                                                                                                                                                                                                                                                                                                                            throw new Error('Your company account is not approved.')
                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                            const { data: companyStatus, error: companyError } =
                                                                                                                                                                                                                                                                                                                                                      await supabase.rpc('current_company_status')

                                                                                                                                                                                                                                                                                                                                                              if (companyError) throw companyError
                                                                                                                                                                                                                                                                                                                                                                      if (companyStatus !== 'active') {
                                                                                                                                                                                                                                                                                                                                                                                throw new Error('Your company is not active.')
                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                if (!cancelled) setAccountType('company')
                                                                                                                                                                                                                                                                                                                                                                                                      } catch (error) {
                                                                                                                                                                                                                                                                                                                                                                                                              console.error('Account verification:', error)
                                                                                                                                                                                                                                                                                                                                                                                                                      if (!cancelled) {
                                                                                                                                                                                                                                                                                                                                                                                                                                setAccountType(null)
                                                                                                                                                                                                                                                                                                                                                                                                                                          await supabase.auth.signOut()
                                                                                                                                                                                                                                                                                                                                                                                                                                                  }
                                                                                                                                                                                                                                                                                                                                                                                                                                                        } finally {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (!cancelled) setCheckingAccess(false)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                              verifyAccount()

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  return () => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        cancelled = true
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }, [session])

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (loading || (session && checkingAccess)) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    return (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <div style={centerStyle}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <h2 style={{ color: '#2865e8', letterSpacing: 3 }}>CODEVEX</h2>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <p>Loading secure workspace...</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (!session) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                return <Auth onLogin={() => {}} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (accountType === 'platform') {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        return <SuperAdmin />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (accountType === 'company') {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                return (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <div style={barStyle}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <strong>CODEVEX</strong>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <button
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              style={logoutStyle}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          onClick={() => supabase.auth.signOut()}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    >
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                Sign out
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <App />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        return <Auth onLogin={() => {}} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const centerStyle: React.CSSProperties = {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          minHeight: '100vh',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            display: 'grid',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              placeItems: 'center',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                textAlign: 'center',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  background: '#f3f5f9',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    color: '#64748b',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      fontFamily: 'Arial, sans-serif',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const barStyle: React.CSSProperties = {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        height: 48,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          padding: '0 18px',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            display: 'flex',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              alignItems: 'center',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                justifyContent: 'space-between',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  background: '#101a30',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    color: '#fff',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      position: 'relative',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        zIndex: 20,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const logoutStyle: React.CSSProperties = {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          background: '#263957',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            border: '1px solid #40516d',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              color: '#fff',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                padding: '7px 13px',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  borderRadius: 7,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    cursor: 'pointer',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    createRoot(document.getElementById('root')!).render(window.location.pathname === '/about' ? <PublicInfoPage kind="about" /> : window.location.pathname === '/privacy-policy' ? <PublicInfoPage kind="privacy" /> : <Root />)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    